create extension if not exists pgcrypto;
create type public.app_role as enum ('administrator','planner','store','supplier','quality_inspector','manager');
create type public.job_status as enum ('pending','active','delayed','completed','blocked','archived');
create table public.organizations(id uuid primary key default gen_random_uuid(),name text not null,code text not null unique,created_at timestamptz not null default now());
create table public.user_profiles(id uuid primary key references auth.users(id) on delete cascade,organization_id uuid references public.organizations(id),full_name text not null,role public.app_role not null,created_at timestamptz not null default now());
create table public.suppliers(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),name text not null,contact_person text,email text,phone text,location text,processes text[] not null default '{}',active boolean not null default true,created_at timestamptz not null default now(),unique(organization_id,name));
create table public.job_orders(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),job_number text not null, title text not null,product text not null,material text not null,quantity numeric not null check(quantity>0),unit text not null,priority text not null check(priority in('low','normal','high')),start_date date not null,due_date date not null check(due_date>=start_date),status public.job_status not null default 'pending',instructions text,created_by uuid references auth.users(id),closed_at timestamptz,created_at timestamptz not null default now(),unique(organization_id,job_number));
create table public.job_stages(id uuid primary key default gen_random_uuid(),job_id uuid not null references public.job_orders(id) on delete cascade,sequence int not null check(sequence>0),name text not null,supplier_id uuid references public.suppliers(id),planned_start date,planned_end date,status text not null default 'pending',quantity numeric not null check(quantity>=0),instructions text,actual_start timestamptz,actual_end timestamptz,unique(job_id,sequence));
create table public.material_movements(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),job_id uuid not null references public.job_orders(id),stage_id uuid references public.job_stages(id),movement_type text not null check(movement_type in('dispatch','receipt','partial_return','full_return','adjustment')),from_location text not null,to_location text not null,quantity numeric not null check(quantity>0),unit text not null,document_reference text,status text not null,related_movement_id uuid references public.material_movements(id),recorded_by uuid references auth.users(id),occurred_at timestamptz not null default now(),created_at timestamptz not null default now());
create table public.production_updates(id uuid primary key default gen_random_uuid(),stage_id uuid not null references public.job_stages(id),completed_quantity numeric not null check(completed_quantity>=0),scrap_quantity numeric not null default 0 check(scrap_quantity>=0),note text,created_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.quality_inspections(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),job_id uuid not null references public.job_orders(id),movement_id uuid references public.material_movements(id),inspected numeric not null check(inspected>=0),accepted numeric not null check(accepted>=0),rework numeric not null check(rework>=0),rejected numeric not null check(rejected>=0),notes text,inspected_by uuid references auth.users(id),created_at timestamptz not null default now(),constraint dispositions_equal_inspected check(accepted+rework+rejected=inspected));
create table public.rework_records(id uuid primary key default gen_random_uuid(),inspection_id uuid not null references public.quality_inspections(id),quantity numeric not null check(quantity>0),status text not null,created_at timestamptz not null default now());
create table public.reconciliation_records(id uuid primary key default gen_random_uuid(),job_id uuid not null references public.job_orders(id),issued numeric not null,accepted numeric not null default 0,rejected numeric not null default 0,unused_returned numeric not null default 0,rework_pending numeric not null default 0,wip numeric not null default 0,in_transit numeric not null default 0,other numeric not null default 0,notes text,investigation_status text not null default 'open',exception_approved_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.alerts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),job_id uuid references public.job_orders(id),category text not null,description text not null,severity text not null check(severity in('low','medium','high')),owner_id uuid references auth.users(id),status text not null default 'open' check(status in('open','investigating','resolved')),created_at timestamptz not null default now(),resolved_at timestamptz);
create table public.documents(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),job_id uuid references public.job_orders(id),path text not null,file_name text not null,mime_type text,uploaded_by uuid references auth.users(id),created_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id),actor_id uuid references auth.users(id),entity_type text not null,entity_id uuid not null,action text not null,details jsonb not null default '{}',created_at timestamptz not null default now());
create index job_orders_org_status_idx on public.job_orders(organization_id,status);create index stages_job_idx on public.job_stages(job_id,sequence);create index movements_job_date_idx on public.material_movements(job_id,occurred_at desc);create index alerts_org_status_idx on public.alerts(organization_id,status);
alter table public.organizations enable row level security;alter table public.user_profiles enable row level security;alter table public.suppliers enable row level security;alter table public.job_orders enable row level security;alter table public.job_stages enable row level security;alter table public.material_movements enable row level security;alter table public.production_updates enable row level security;alter table public.quality_inspections enable row level security;alter table public.reconciliation_records enable row level security;alter table public.alerts enable row level security;alter table public.documents enable row level security;alter table public.audit_logs enable row level security;
create function public.current_org() returns uuid language sql stable security definer set search_path=public as $$select organization_id from public.user_profiles where id=auth.uid()$$;
create policy org_jobs on public.job_orders for select using(organization_id=public.current_org());create policy org_suppliers on public.suppliers for select using(organization_id=public.current_org());create policy org_movements on public.material_movements for select using(organization_id=public.current_org());create policy org_quality on public.quality_inspections for select using(organization_id=public.current_org());create policy org_alerts on public.alerts for select using(organization_id=public.current_org());create policy own_profile on public.user_profiles for select using(id=auth.uid());
